interactions.sample_code:
function insertionSort() {
  markPrefix(1);
  for (let j = 2; j <= size(); j++) {
    let k = j;
    markKey(k);
    note("Insert the next key into the sorted prefix.");

    while (k > 1 && compare(k - 1, k)) {
      shift(k);
      k = k - 1;
      markKey(k);
    }

    markPrefix(j);
  }
  markKey(0);
  note("The entire array is sorted.");
}

